// ── Account helpers ──────────────────────────────────────────────

fn signer(address: Pubkey) -> Account {
    quasar_svm::token::create_keyed_system_account(&address, 10_000_000_000)
}

fn empty(address: Pubkey) -> Account {
    Account {
        address,
        lamports: 0,
        data: vec![],
        owner: quasar_svm::system_program::ID,
        executable: false,
    }
}

/// Create a pre-populated HaircutconservationAccount account (program-owned).
fn state_account(
    address: Pubkey,
    credited: u128,
    bump: u8,
) -> Account {
    let state = HaircutconservationAccount {
        credited,
        bump,
    };
    Account {
        address,
        lamports: 2_000_000,
        data: wincode::serialize(&state).unwrap(),
        owner: crate::ID,
        executable: false,
    }
}

